package main

import("encoding/binary";"encoding/json";"fmt";"os";"path/filepath";"sort";"strings";"math";"crypto/sha256";"encoding/hex")
type Field struct { Name string; ID int64 }
type Type struct { Name string; Kind string; Fields []Field; Elem int64; Key int64; Len int64 }
type Reader struct { B []byte; P int }
func(r *Reader)u()uint64{if r.P>=len(r.B){panic("eof")};b:=r.B[r.P];r.P++;if b<=127{return uint64(b)};n:=-int(int8(b));if n>8||r.P+n>len(r.B){panic("uint")};var x uint64;for i:=0;i<n;i++{x=x<<8|uint64(r.B[r.P]);r.P++};return x}
func(r *Reader)i()int64{x:=r.u();if x&1!=0{return ^int64(x>>1)};return int64(x>>1)}
func(r *Reader)bytes()[]byte{n:=int(r.u());if n<0||r.P+n>len(r.B){panic("bytes")};b:=r.B[r.P:r.P+n];r.P+=n;return b}
var types map[int64]Type
func val(r *Reader,id int64)any{switch id{case 1:return r.u()!=0;case 2:return r.i();case 3:return r.u();case 4:u:=r.u();var b [8]byte;binary.LittleEndian.PutUint64(b[:],u);return math.Float64frombits(binary.BigEndian.Uint64(b[:]));case 5:return r.bytes();case 6:return string(r.bytes());case 8:panic("interface value unsupported")};t,ok:=types[id];if !ok{panic(fmt.Sprintf("unknown type %d",id))};switch t.Kind{case "struct":m:=map[string]any{};idx:=-1;for{d:=int(r.u());if d==0{break};idx+=d;if idx>=len(t.Fields){panic("field")};f:=t.Fields[idx];m[f.Name]=val(r,f.ID)};return m;case "slice","array":n:=int(r.u());a:=make([]any,n);for j:=range a{a[j]=val(r,t.Elem)};return a;case "map":n:=int(r.u());m:=map[string]any{};for j:=0;j<n;j++{k:=val(r,t.Key);m[fmt.Sprint(k)]=val(r,t.Elem)};return m;case "external":return r.bytes()};panic("kind")}
func initTypes(){types=map[int64]Type{16:{Name:"wireType",Kind:"struct",Fields:[]Field{{"ArrayT",17},{"SliceT",19},{"StructT",20},{"MapT",23},{"GobEncoderT",24},{"BinaryMarshalerT",24},{"TextMarshalerT",24}}},17:{Name:"arrayType",Kind:"struct",Fields:[]Field{{"CommonType",18},{"Elem",2},{"Len",2}}},18:{Name:"CommonType",Kind:"struct",Fields:[]Field{{"Name",6},{"Id",2}}},19:{Name:"sliceType",Kind:"struct",Fields:[]Field{{"CommonType",18},{"Elem",2}}},20:{Name:"structType",Kind:"struct",Fields:[]Field{{"CommonType",18},{"Field",21}}},21:{Name:"fields",Kind:"slice",Elem:22},22:{Name:"fieldType",Kind:"struct",Fields:[]Field{{"Name",6},{"Id",2}}},23:{Name:"mapType",Kind:"struct",Fields:[]Field{{"CommonType",18},{"Key",2},{"Elem",2}}},24:{Name:"gobEncoderType",Kind:"struct",Fields:[]Field{{"CommonType",18}}}}}
func definition(id int64,m map[string]any){for k,v:=range m{x:=v.(map[string]any);c:=x["CommonType"].(map[string]any);t:=Type{Name:c["Name"].(string)};switch k{case "ArrayT":t.Kind="array";t.Elem=x["Elem"].(int64);t.Len=x["Len"].(int64);case "SliceT":t.Kind="slice";t.Elem=x["Elem"].(int64);case "StructT":t.Kind="struct";if fs,ok:=x["Field"].([]any);ok{for _,f:=range fs{z:=f.(map[string]any);t.Fields=append(t.Fields,Field{z["Name"].(string),z["Id"].(int64)})}};case "MapT":t.Kind="map";t.Elem=x["Elem"].(int64);t.Key=x["Key"].(int64);default:t.Kind="external"};types[id]=t}}
func digest(b []byte)string{h:=sha256.Sum256(b);return hex.EncodeToString(h[:])}
func shape(v any)any{switch x:=v.(type){case map[string]any:m:=map[string]any{};for k,z:=range x{m[k]=shape(z)};return m;case []any:if len(x)>0{return map[string]any{"count":len(x),"first_shape":shape(x[0])}};return map[string]any{"count":0};case []byte:return map[string]any{"kind":"bytes","length":len(x),"sha256":digest(x)};case string:return map[string]any{"kind":"string","length":len(x),"sha256":digest([]byte(x))};default:return x}}
func decode(b []byte)(v any,err string){defer func(){if e:=recover();e!=nil{err=fmt.Sprint(e)}}();initTypes();if len(b)>=8&&int(binary.LittleEndian.Uint32(b[:4]))==len(b)-8{b=b[8:]};r:=&Reader{B:b};for r.P<len(b){n:=int(r.u());end:=r.P+n;if end>len(b){panic("message")};q:=&Reader{B:r.B[r.P:end]};id:=q.i();if id<0{definition(-id,val(q,16).(map[string]any))}else{if types[id].Kind!="struct"{q.u()};v=val(q,id)};if q.P!=len(q.B){panic(fmt.Sprintf("unconsumed bytes %d id %d consumed %d total %d",len(q.B)-q.P,id,q.P,len(q.B)))};r.P=end};return}
func main(){files,_:=filepath.Glob(filepath.Join(os.Args[1],"*.gob"));sort.Strings(files);results:=[]any{};for _,p:=range files{b,e:=os.ReadFile(p);if e!=nil{continue};v,err:=decode(b);m:=map[string]any{"file":filepath.Base(p),"bytes":len(b)};if err!=""{m["error"]=err}else{m["shape"]=shape(v)};results=append(results,m);if len(os.Args)>2&&os.Args[2]=="one"{schema:=map[int64]Type{};for k,t:=range types{if k>=64{schema[k]=t}};m["schema"]=schema;break}};enc:=json.NewEncoder(os.Stdout);enc.SetIndent("","  ");enc.Encode(results);_ = strings.Contains}
